import type { RuleSection } from '../refereeTypes';

type LessonContent = { minutes: number; sections: RuleSection[]; questionSections: string[] };

// Independently authored teaching, with an explicit reading destination for
// each question in the existing quiz. Content updates do not invalidate scores.
function section(id: string, title: string, body: string, references: [string, ...string[]], scenario: string, ruling: string, pitfall: string): RuleSection {
  return { id, title, body, reference: references[0], additionalReferences: references.slice(1), example: { scenario, ruling }, pitfall };
}

